mapper.sql:
select * from ( SELECT ptm.id, pm.id as managementId, pm.process_instance_id, pm.process_definition_id, pm.process_version , pm.process_status , pm.process_name , pm.business_id , pm.business_code , pm.business_name , pm.business_key, pm.act_process_definition_id , ptm.cur_approve_id , ptm.cur_activity_id, ptm.cur_activity_name, ptm.task_id, ptm.task_status, ptm.cur_approve_name AS cur_approve_name, concat(wm.detail_url,pm.business_id) as detail_url, pm.create_time as createTime, pm.update_time as updateTime, pm.create_user_id as createUserId, ptm.label_json, ptm.approve_time, pm.end_time, 'erp' as sourcePlatform FROM process_task_management AS ptm LEFT JOIN process_management AS pm on pm.process_instance_id = ptm.process_instance_id AND pm.is_deleted = false LEFT JOIN work_menu AS wm on pm.business_key = wm.module_code AND wm.is_deleted = false where ptm.is_deleted = false union all select tptm.id, tpm.id as managementId, tpm.process_instance_id, tpm.process_definition_id, null as process_version , tpm.status as process_status , tpm.process_instance_name as process_name , tpm.business_id , tpm.business_code , '' as business_name , tpm.business_key, '' as act_process_definition_id , tptm.sys_user_id as cur_approve_id , tptm.node_id as cur_activity_id, tptm.node_name as cur_activity_name, tptm.task_id, tptm.task_status, '' AS cur_approve_name, '' as detail_url, tpm.create_time as createTime, tpm.update_time as updateTime, tpm.create_user_id as createUserId, null as label_json, case when tptm.task_status = 'approve' then tptm.end_time else null end as approve_time, tpm.end_time, 'fs' as sourcePlatform from third_process_task_management tptm inner join third_process_management tpm on tptm.main_id = tpm.id and tpm.is_deleted = false where tptm.is_deleted = false ) pp where ${param.sqlMap.default}
and (pp.label_json ->> 'isDelegate')::boolean is true
order by pp.createTime desc

mapper.select:
AND approve_status = 'approveIng' AND pm.business_id = #{businessId} AND pm.business_key = #{businessKey} AND ptm.task_status = 'approveIng'
AND ptm.cur_approve_id = #{userId}
ORDER BY ptm.create_time ASC LIMIT 1

SELECT pm.process_status as tabFlag, count(pm.id) as count FROM process_task_management AS ptm LEFT JOIN process_management AS pm on pm.process_instance_id = ptm.process_instance_id AND pm.is_deleted = false WHERE ptm.is_deleted = FALSE
${params.permissionSql}
group by pm.process_status
